module multi_pipe_8bit #(
    parameter size = 8
) (
    input clk,
    input rst_n,
    input [size-1:0] mul_a,
    input [size-1:0] mul_b,
    input mul_en_in,
    output reg mul_en_out,
    output reg [size*2-1:0] mul_out
);

    parameter WIDTH = 8;
    parameter PRODUCT_WIDTH = 16;

    reg [WIDTH-1:0] mul_en_out_reg;
    reg [WIDTH-1:0] mul_a_reg;
    reg [WIDTH-1:0] mul_b_reg;
    wire [WIDTH-1:0] temp [WIDTH-1:0];
    reg [WIDTH:0] sum [WIDTH:0];
    reg [PRODUCT_WIDTH-1:0] mul_out_reg;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            mul_en_out_reg <= 0;
            mul_a_reg <= 0;
            mul_b_reg <= 0;
        end else begin
            mul_en_out_reg <= {mul_en_out_reg[1:0], mul_en_in};
            mul_a_reg <= mul_a;
            mul_b_reg <= mul_b;
        end
    end

    generate
        genvar i;
        for (i = 0; i < WIDTH; i = i + 1) begin : partial_product_gen
            assign temp[i] = {temp[i][WIDTH-2:0], mul_a_reg & mul_b_reg[i]};
        end
    endgenerate

    always @(posedge clk) begin
        if (mul_en_out_reg[2]) begin
            sum[0] <= temp[0] + temp[1];
            sum[1] <= temp[2] + temp[3];
            sum[2] <= temp[4] + temp[5];
            sum[3] <= temp[6] + temp[7];
        end
    end

    always @(posedge clk) begin
        if (mul_en_out_reg[2]) mul_out_reg <= sum[0] + sum[1] + sum[2] + sum[3]; else mul_out_reg <= 0;
    end

    assign mul_en_out = mul_en_out_reg[2];

endmodule
